# -*- coding: utf-8 -*- import whisper, os  def probe_language():     input_wav = r"E:\VideoTranslator_Project\unhinged_tech\aligned_input.wav"     print("\n--- 🔍 正在执行【全球语言大普查】 ---")          # 加载 base 模型进行语言探测 (探测不需要 large)     model = whisper.load_model("base")          # 截取音频中部 (通常中间说话最稳)     audio = whisper.load_audio(input_wav)     audio = whisper.pad_or_trim(audio)          mel = whisper.log_mel_spectrogram(audio).to(model.device)     _, probs = model.detect_language(mel)          detected_lang = max(probs, key=probs.get)     print(f"🚩 最终判定：此视频的母语是 -> 【{detected_lang}】")     print(f"📊 概率分布 top3: {sorted(probs.items(), key=lambda x: x[1], reverse=True)[:3]}")  if __name__ == "__main__":     probe_language()
